mod solution;

fn main() {
    assert_eq!(solution::save_report(std::path::Path::new(if cfg!(target_arch = "wasm32") { "/sandbox/crabrix-report.txt" } else { "crabrix-report.txt" }), "crab: 3\n").unwrap(), "crab: 3\n", "case 1");
    assert_eq!(solution::save_report(std::path::Path::new(if cfg!(target_arch = "wasm32") { "/sandbox/crabrix-report.txt" } else { "crabrix-report.txt" }), "").unwrap(), "", "case 2");
    assert_eq!(solution::save_report(std::path::Path::new(if cfg!(target_arch = "wasm32") { "/sandbox/crabrix-report.txt" } else { "crabrix-report.txt" }), "Rust 🦀\nnext").unwrap(), "Rust 🦀\nnext", "case 3");

    println!("PASS sandbox-file-roundtrip");
}
